"use server";

import { requireAdmin } from "@/lib/auth";
import type { Locale } from "@/lib/i18n/config";
import longtail from "@/lib/seo/longtail.json";

// Keyword suggestions for one product, from the refined keyword research
// (seo/refined, regenerated by scripts/seo/refine_keywords.py). Runs on the
// server so the 12k-keyword list never ships to the browser.

const LISTS = longtail as Record<Locale, string[]>;

const normalize = (s: string) =>
  s
    .normalize("NFD")
    .replace(/[̀-ͯ]/g, "")
    .toLowerCase()
    .replace(/[^a-z0-9.\s]/g, " ");

const STOP = new Set(["the", "and", "bag", "bags", "with", "for", "de", "la", "le", "of"]);

export async function suggestKeywords(brand: string, name: string, locale: Locale): Promise<string[]> {
  await requireAdmin();

  const brandTokens = normalize(brand).split(/\s+/).filter((t) => t.length > 1);
  const nameTokens = normalize(name)
    .split(/\s+/)
    .filter((t) => t.length > 1 && !STOP.has(t) && !brandTokens.includes(t));
  if (nameTokens.length === 0) return [];

  const scored: { kw: string; score: number }[] = [];
  for (const kw of LISTS[locale] ?? []) {
    const words = new Set(normalize(kw).split(/\s+/));
    // Must mention the model (first meaningful word of the name, e.g. "birkin").
    if (!words.has(nameTokens[0])) continue;
    const hits = nameTokens.filter((t) => words.has(t)).length + (brandTokens.some((t) => words.has(t)) ? 1 : 0);
    scored.push({ kw, score: hits * 10 - words.size });
  }

  return scored
    .sort((a, b) => b.score - a.score)
    .slice(0, 15)
    .map((s) => s.kw);
}
